    raise SystemExit(f"unexpected head {head}")

print("=== tests ===")
for p in sorted((wt/"tests").glob("test_*.py")):
    print(p.name)

for rel in ["tests/test_agent.py", "tests/test_core.py", "tests/test_safety.py"]:
