    if not p.exists():
        continue
    print(f"=== {rel} ===")
    lines=p.read_text().splitlines()
    for n,line in enumerate(lines,1):
        if any(k in line for k in ["validate_request(", "make_request", "request_id", "receipt_callback", "Agent("]):
            start=max(1,n-4); end=min(len(lines),n+12)
